pub const TokenList = struct {
    v: std.ArrayListUnmanaged(TokenOrValue) = .{},

pub fn deinit(self: *TokenList, allocator: Allocator) void {
            for (self.v.items) |*token_or_value| {
                _ = &token_or_value;
                _ = (token_or_value.*).deinit(allocator);
            }
            _ = self.v.deinit(allocator);
    }

pub fn toCss(self: TokenList, dest: *Printer, is_custom_property: bool) PrintErr!void {
            if ((((!dest.minify) and (self.v.items.len == 1)) and self.v.items[0].isWhitespace())) {
                return;
            }
            var has_whitespace = false;
            _ = &has_whitespace;
            var i: usize = 0;
            _ = &i;
            while ((i < self.v.items.len)) : (i = (i + 1)) {
                const token_or_value = (&self.v.items[@as(usize, @intCast(i))]);
                switch (token_or_value.*) {
.color => |color| {
_ = try color.toCss(dest);
                has_whitespace = false;
},
.unresolved_color => |color| {
_ = try color.toCss(dest, is_custom_property);
                has_whitespace = false;
},
.url => |url| {
if (((dest.dependencies != null) and is_custom_property)) {
                    const recs = try dest.getImportRecords();
                    if ((!url.isAbsolute(recs))) {
                        return dest.newError(css.PrinterErrorKind{ .ambiguous_url_in_custom_property = .{ .url = recs.at(url.import_record_idx).path.pretty } }, url.loc);
                    }
                }
                _ = try url.toCss(dest);
                has_whitespace = false;
},
.@"var" => |var_val| {
_ = try var_val.toCss(dest, is_custom_property);
                has_whitespace = try self.writeWhitespaceIfNeeded(i, dest);
},
.env => |env| {
_ = try env.toCss(dest, is_custom_property);
                has_whitespace = try self.writeWhitespaceIfNeeded(i, dest);
},
.function => |f| {
_ = try f.toCss(dest, is_custom_property);
                has_whitespace = try self.writeWhitespaceIfNeeded(i, dest);
},
.length => |v| {
const vu = v.toUnitValue();
                const value = vu[0];
                const unit = vu[1];
                _ = try css.serializer.serializeDimension(value, unit, dest);
                has_whitespace = false;
},
.angle => |v| {
_ = try v.toCss(dest);
                has_whitespace = false;
},
.time => |v| {
_ = try v.toCss(dest);
                has_whitespace = false;
},
.resolution => |v| {
_ = try v.toCss(dest);
                has_whitespace = false;
},
.dashed_ident => |v| {
_ = try DashedIdentFns.toCss(v, dest);
                has_whitespace = false;
},
.animation_name => |v| {
var av = v;
                _ = &av;
                _ = try av.toCss(dest);
                has_whitespace = false;
},
.token => |token| {
