.delim => |d| {
if (((d == 43) or (d == 45))) {
                    _ = try dest.writeChar(32);
                    _ = bun.assert((d <= 127));
                    _ = try dest.writeChar(@intCast(d));
                    _ = try dest.writeChar(32);
                } else {
                    const ws_before = ((!has_whitespace) and ((d == 47) or (d == 42)));
                    _ = bun.assert((d <= 127));
                    _ = try dest.delim(@intCast(d), ws_before);
                }
                has_whitespace = true;
},
.comma => {
_ = try dest.delim(44, false);
                has_whitespace = true;
},
.close_paren, .close_square, .close_curly => {
_ = try token.toCss(dest);
                has_whitespace = try self.writeWhitespaceIfNeeded(i, dest);
},
.dimension => {
_ = try css.serializer.serializeDimension((if (@typeInfo(@TypeOf(token.dimension.num)) == .@"enum") @intFromEnum(token.dimension.num) else token.dimension.num.value), token.dimension.unit, dest);
                has_whitespace = false;
},
.number => |v| {
_ = try css.css_values.number.CSSNumberFns.toCss((&(if (@typeInfo(@TypeOf(v)) == .@"enum") @intFromEnum(v) else v.value)), dest);
                has_whitespace = false;
},
else => {
_ = try token.toCss(dest);
                has_whitespace = (token == .whitespace);
},
}
},
}
            }
    }

pub fn toCssRaw(self: TokenList, dest: *Printer) PrintErr!void {
            for (self.v.items) |token_or_value| {
                _ = &token_or_value;
                if ((token_or_value == .token)) {
                    _ = try token_or_value.token.toCss(dest);
                } else {
                    return dest.addFmtError();
                }
            }
    }

pub fn writeWhitespaceIfNeeded(self: TokenList, i: usize, dest: *Printer) PrintErr!bool {
            if ((((!dest.minify) and (i != (self.v.items.len - 1))) and (!((self.v.items[@as(usize, @intCast((i + 1)))] == .token) and (switch (self.v.items[@as(usize, @intCast((i + 1)))].token) {
.comma, .close_paren => true,
else => false,
}))))) {
